interface Deferred {
  promise: Promise<string[]>;
  resolve: (value: string[]) => void;
}

function deferred(): Deferred {
  let resolve!: (value: string[]) => void;
  const promise = new Promise<string[]>((done) => {
    resolve = done;
  });
  return { promise, resolve };
}

